function findings(){const ns=allNodes().filter(n=>!n.ghost);const es=allEdges().filter(e=>ns.some(n=>n.id===e.from)&&ns.some(n=>n.id===e.to));const ids=new Set(ns.map(n=>n.id));const dangling=edges.filter(e=>!ids.has(e.from)||!ids.has(e.to));return [
  {ok:dangling.length===0,title:'Relationship integrity',text:`${es.length} relationships resolve to model objects. ${dangling.length} missing endpoints.`},
  {ok:true,title:'Logical → physical traceability',text:'All 5 logical responsibilities link to a candidate implementation.'},
  {ok:s.accepted.includes('review'),title:'Held-payment ownership',text:s.accepted.includes('review')?'Manual review candidate added. Release authority and SLA still require evidence.':'Risk can hold a payment; add a review responsibility to make the next action explicit.',suggest:'review'},
  {ok:s.accepted.includes('dedup'),title:'Duplicate handling',text:s.accepted.includes('dedup')?'Idempotency candidate added. Atomicity and retention still require review.':'Core ledger has an integrity obligation but no explicit idempotency record.',suggest:'dedup'},
  {ok:s.accepted.includes('recovery'),title:'Uncertain settlement recovery',text:s.accepted.includes('recovery')?'Recovery candidate added. Enquiry behaviour and operating runbook still require review.':'The settlement implementation needs an explicit path for uncertain outcomes.',suggest:'recovery'},
  {ok:false,title:'Evidence and independent review',text:'Capacity, security controls, failover, contract behaviour, and governance approval remain outside this prototype.'}
]}
function validateSurface(){if(studio)return studio.validation();return `<article class="content-card"><div class="eyebrow">Chapter ${s.chapter} · Validate</div><h2>Make the design defensible.</h2><p>Check the connected model and expose the decisions still needing evidence.</p><button class="btn primary" data-action="validate">${icon('shield')}${done('validate')?'Run checks again':'Run model checks'}</button><div class="readiness">Working draft · Structural checks do not imply production readiness.</div>${done('validate')?findings().map(f=>`<div class="validation-row"><span class="status-icon ${f.ok?'':'warn'}">${f.ok?'✓':'!'}</span><div><b>${f.title}</b><p>${f.text}</p></div>${f.suggest&&!s.accepted.includes(f.suggest)?`<button class="text-button" data-propose="${f.suggest}">Explore fix</button>`:''}</div>`).join(''):`<div class="checklist"><p>Checks cover object references, implementation mappings, review ownership, duplicate protection, and recovery.</p></div>`}</article>`}
function outputSurface(){if(studio)return studio.output();return `<article class="content-card"><div class="eyebrow">Chapter ${s.chapter} · Output</div><h2>A model you can explain.</h2><p>The Payment API accepts an instruction, Risk screening allows or holds it, Core ledger records the posting, and Settlement hub handles the external outcome. Notification service closes the loop.</p><table class="output-table"><thead><tr><th>Responsibility</th><th>Candidate implementation</th></tr></thead><tbody>${['api','risk','ledger','hub','notify'].map((id,i)=>`<tr><td><button class="object-link" data-select="${id}">${getNode(id).title}</button></td><td><button class="object-link" data-select="${['api-pod','risk-engine','core-adapter','worker','notify-worker'][i]}">${getNode(['api-pod','risk-engine','core-adapter','worker','notify-worker'][i]).title}</button></td></tr>`).join('')}</tbody></table><div class="eyebrow">Your working changes</div><p>${s.accepted.length?s.accepted.map(id=>esc(suggestions[id].title)).join(' · '):'No additional candidates yet. Preview a ghost suggestion from the model to explore a change.'}</p>${s.note?`<div class="context-ribbon"><b>Architect’s note</b><br>${esc(s.note)}</div>`:''}<div class="readiness">Not approved for implementation. Open obligations and review findings are included in the export.</div><div class="action-row"><button class="btn primary" data-action="export">${icon('download')}Export model JSON</button><button class="btn" data-action="export-summary">${icon('file')}Export reading</button></div><details class="disclosure"><summary>What is included?</summary><p>The full model, typed relationships, retained candidates, architecture notes, current view, exploration milestones, and open review findings. Browser-only state is not shared across devices.</p></details></article>`}
function suggestFor(n){if(s.tab==='validate')return !s.accepted.includes('dedup')?'dedup':!s.accepted.includes('recovery')?'recovery':'review';if(s.chapter===4)return n.id==='ledger'||n.layer==='data'?'dedup':'review';return ['ledger','core-adapter','posting','posting-api'].includes(n.id)?'dedup':n.id.includes('risk')?'review':'recovery'}
function contextFor(n){const title=n.title;return s.tab==='work'?`Frame the decision: who owns ${title}, and which quality driver justifies it?`:s.tab==='validate'?`Challenge ${title}: confirm its contract, failure behaviour, and review evidence.`:s.tab==='output'?`Explain ${title}: carry its responsibility, mapping, and open obligations into the handoff.`:s.chapter===4?`Chapter 4 · Understand what ${title} is responsible for and what it depends on.`:`Chapter 5 · Inspect how ${title} is realised, connected, and operated.`}
function inspector(){if(studio)return studio.inspector(getNode(s.selected));const n=getNode(s.selected),l=layerOf(n),rels=allEdges().filter(e=>e.from===n.id||e.to===n.id),sid=s.ghost||suggestFor(n),sg=suggestions[sid];return `<header class="inspector-top">${icon('cursor')}Object lens<span class="tiny-badge">${s.tab==='model'?'Selected':s.tab[0].toUpperCase()+s.tab.slice(1)}</span></header><div class="inspector-body"><div class="object-icon" style="color:${l.color}">${icon(l.icon)}</div><div class="eyebrow">${n.ghost?'Ghost proposal':n.accepted?'Working candidate':l.name}</div><h2>${esc(n.title)}</h2><button class="text-button mobile-return" data-action="back-canvas">↑ Return to model</button><p>${n.description}</p><div class="context-ribbon">${esc(contextFor(n))}</div><div class="eyebrow">Attributes</div><dl class="attribute-list">${Object.entries(n.attrs).map(([k,v])=>`<div class="attribute"><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${sourceRequirements(n.id)}${sourceQualityDrivers(n.id)}${sourceDecisions(n.id)}<div class="eyebrow relation-heading">Relationships · ${rels.length}</div><div class="relation-list">${rels.slice(0,4).map(e=>{const other=getNode(e.from===n.id?e.to:e.from);return `<button class="relation" data-select="${other.id}">${e.from===n.id?esc(e.label):`${esc(e.label)} ←`}<strong>${other.title}</strong>${!s.visible.includes(other.layer)?`<small>Reveal ${layerOf(other).name.toLowerCase()} layer</small>`:''}</button>`}).join('')}</div>${rels.length>4?`<button class="text-button" data-action="all-relations">View all ${rels.length} relationships</button>`:''}<div class="suggestion-card"><div class="suggestion-label">${icon('spark')}${s.ghost?'Previewing a change':'A useful next thought'}</div><h3>${sg.title}</h3><p>${s.ghost?sg.effect:sg.reason}</p>${s.accepted.includes(sid)?`<button class="btn" data-remove="${sid}">${icon('rewind')}Undo working candidate</button>`:s.ghost?`<div class="action-row"><button class="btn gold" data-accept="${sid}">${icon('check')}Add to working model</button><button class="text-button" data-action="dismiss">Dismiss preview</button></div>`:`<button class="btn" data-propose="${sid}">${icon('plus')}Preview ghost suggestion</button>`}</div></div>`}
function refreshInspector(){if(window.history){const route=new URLSearchParams({chapter:String(s.chapter),tab:s.tab,object:s.selected});window.history.replaceState({},'',projectURL(location.pathname+'?'+route))}if($('#inspector'))$('#inspector').innerHTML=inspector();refineWorkspace(s.tab,{chapter:s.chapter,id:s.selected})}
function selectNode(id,fromPointer=false){if(!allNodes().some(n=>n.id===id)){toast('This object is unavailable in the current perspective. Reveal its layer or choose another object.');return}const n=getNode(id),revealed=!s.visible.includes(n.layer);s.selected=n.id;if(revealed)s.visible.push(n.layer);if(!n.ghost)mark('inspect');if(n.layer==='physical')mark('physical');persist();if(s.tab==='model'){if(revealed)render();else{drawGraph();refreshInspector()}}else refreshInspector();if(!fromPointer&&s.tab==='model')toast(`${esc(n.title)} · ${layerOf(n).name}`)}
function nodeTitleMarkup(title){const words=String(title).split(/\s+/),lines=[''];for(const word of words){let i=lines.length-1;if(lines[i].length+word.length+1>25&&lines[i]){if(i===1){lines[i]=lines[i].slice(0,22)+'…';break}lines.push(word)}else lines[i]+=(lines[i]?' ':'')+word}return `<text x="13" y="${lines.length>1?47:52}" font-size="14" font-weight="500" fill="#3c5835">${lines.map((line,i)=>`<tspan x="13" dy="${i?17:0}">${esc(line.length>26?line.slice(0,23)+'…':line)}</tspan>`).join('')}</text>`}
function drawGraph(){
  const svg=$('#graph');if(!svg)return;
  const ns=visibleNodes(),mobile=isMobile(),layout=layoutModel(ns,mobile,s.focus,s.grouped);
  positions=layout.positions;graphHeight=layout.height;graphWidth=layout.width;
  const lanes=layout.lanes.map(l=>`<text class="lane-label" x="28" y="${l.y}">${l.name.toUpperCase()}</text>`).join('');
  svg.setAttribute('viewBox',`0 0 ${graphWidth} ${graphHeight}`);
  const canvas=$('#canvas');
  canvas.classList.toggle('mobile-graph',mobile);
  svg.setAttribute('preserveAspectRatio','xMinYMin meet');
  const visibleEdges=allEdges().filter(e=>positions.has(e.from)&&positions.has(e.to));const selected=s.selected;const neighbours=new Set([selected,...allEdges().filter(e=>e.from===selected||e.to===selected).map(e=>e.from===selected?e.to:e.from)]);
  const nodeWidth=200,nodeHeight=74;
  let edgeMarkup='';visibleEdges.forEach((e,i)=>{const a=positions.get(e.from),b=positions.get(e.to);const same=a.y===b.y;const x1=same?a.x+nodeWidth:a.x+nodeWidth/2,y1=same?a.y+37:(a.y<b.y?a.y+nodeHeight:a.y),x2=same?b.x:b.x+nodeWidth/2,y2=same?b.y+37:(a.y<b.y?b.y:b.y+nodeHeight);const d=e.decisionId&&!mobile&&same?`M${a.x+nodeWidth/2} ${a.y+nodeHeight} C${a.x+nodeWidth/2} ${a.y+nodeHeight+30},${b.x+nodeWidth/2} ${b.y+nodeHeight+30},${b.x+nodeWidth/2} ${b.y+nodeHeight}`:mobile&&e.kind==='trace'?`M${a.x+200} ${a.y+37} C${350+i%4*12} ${a.y+37},${350+i%4*12} ${b.y+37},${b.x+200} ${b.y+37}`:same?`M${x1} ${y1} C${x1+18} ${y1},${x2-18} ${y2},${x2} ${y2}`:`M${x1} ${y1} C${x1} ${(y1+y2)/2},${x2} ${(y1+y2)/2},${x2} ${y2}`;const related=e.from===selected||e.to===selected;const dim=s.selected&&positions.has(selected)&&!related;edgeMarkup+=`<path id="edge-${i}" class="edge ${e.kind} ${e.changeImpact?'change-affected':''} ${e.impact?'tech-affected':''} ${e.contractTrace?'contract-active':''} ${e.securityTrace?'security-active':''} ${e.runtimeTrace?'runtime-active':''} ${e.ghost?'ghost':''} ${e.decisionId?'decision-link':''} ${related?'highlight':''} ${dim?'dim':''}" d="${d}" marker-end="url(#arrowhead)"/><path class="edge hit" d="${d}" data-edge="${i}"><title>${esc(getNode(e.from).title)} ${esc(e.label)} ${esc(getNode(e.to).title)}</title></path>${e.decisionId&&!mobile&&same?`<text class="edge-label" x="${(a.x+b.x+nodeWidth)/2}" y="${a.y+nodeHeight+26}" text-anchor="middle">${esc(e.decisionId)}</text>`:same?`<text class="edge-label" x="${(x1+x2)/2}" y="${y1-8}" text-anchor="middle">${esc(e.label.length>24?e.label.slice(0,22)+'…':e.label)}</text>`:mobile&&e.kind==='flow'?`<text class="edge-label" x="${x1+12}" y="${(y1+y2)/2+3}">${esc(e.label.length>24?e.label.slice(0,22)+'…':e.label)}</text>`:''}${e.kind==='flow'&&s.animate&&(s.step<0||s.playing)&&(s.step<0||getNode(e.from).col<s.step)&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches?`<circle r="2.7" class="flow-dot" opacity="${dim?.25:.9}"><animateMotion dur="${2.4+i*.05}s" repeatCount="indefinite"><mpath href="#edge-${i}"/></animateMotion></circle>`:''}`;});
  const current=s.step>=0?flowStages()[s.step].node:null;const currentCol=current?getNode(current).col:null;const currentComponents=new Set(current&&studio?allEdges().filter(e=>e.from===current&&getNode(e.to).layer==='physical').map(e=>e.to):[]);
  svg.innerHTML=`<defs><marker id="arrowhead" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="none" stroke="#8ea17e" stroke-width="1"/></marker></defs><g id="graph-world">${lanes}${(layout.groups||[]).map(g=>`<rect class="logical-group-box" x="${g.x}" y="${g.y}" width="${g.width}" height="${g.height}" rx="10"/><text class="logical-group-label" x="${g.x+14}" y="${g.y+22}">${esc(g.title)}</text>`).join('')}${edgeMarkup}${ns.map(n=>{const p=positions.get(n.id),l=layerOf(n);return `<g class="node ${n.changeImpact?'change-affected':''} ${n.securityThreat?'security-threat':''} ${n.ghost?'ghost':''} ${n.impact?'tech-'+n.impact:''} ${n.id===s.selected?'selected':''} ${(n.layer==='physical'&&studio?currentComponents.has(n.id):currentCol===n.col&&['logical','physical','process'].includes(n.layer))?'current-flow':''}" transform="translate(${p.x},${p.y})" data-node="${n.id}" tabindex="0" role="button" aria-label="${esc(n.title)}, ${l.name}${n.ghost?', ghost proposal':''}" aria-pressed="${n.id===s.selected}"><rect class="node-box" width="200" height="74" rx="8"/><rect x="12" y="12" width="22" height="22" rx="6" fill="${l.color}12"/><svg x="16" y="16" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="${l.color}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[l.icon]}"/></svg><text x="42" y="26" font-size="12" fill="${l.color}">${n.ghost?'GHOST PROPOSAL':n.accepted?'WORKING CANDIDATE':n.sub.split(' · ')[0].toUpperCase()}</text>${nodeTitleMarkup(n.title)}${n.id===s.selected?`<circle cx="184" cy="17" r="3" fill="#769251"/>`:''}</g>`}).join('')}</g>`;
  $('#graph-counts').textContent=`${ns.filter(n=>!n.ghost).length} ${ns.filter(n=>!n.ghost).length===1?'object':'objects'}${ns.some(n=>n.ghost)?' + ghost':''} · ${visibleEdges.length} relationships · ${s.visible.length}/8 layers${s.focus?' · Focus view':''}`;
  $('#canvas .empty-state')?.remove();if(!ns.length){const el=document.createElement('div');el.className='empty-state';el.innerHTML=studio?.emptyState?.()||`<h3>A fresh perspective.</h3><p>Select a layer to reveal the connected model.</p><button class="btn" data-action="default-layers">Show process + logical</button>`;$('#canvas').append(el)}
  applyTransform();
  svg.querySelectorAll('[data-node]').forEach(el=>{el.addEventListener('pointerenter',ev=>showTip(el.dataset.node,ev));el.addEventListener('pointermove',ev=>positionTip(ev));el.addEventListener('pointerleave',hideTip);el.addEventListener('focus',()=>showTip(el.dataset.node,null,el));el.addEventListener('blur',hideTip);el.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();hideTip();selectNode(el.dataset.node,true);const target=$(`[data-node="${el.dataset.node}"]`);target?.focus()}if(ev.key==='Escape')hideTip()})});
}
function applyTransform(){const world=$('#graph-world'),svg=$('#graph');if(!world||!svg)return;const zoom=isMobile()?1:s.zoom;svg.style.width=graphWidth*zoom+'px';svg.style.height=graphHeight*zoom+'px';world.setAttribute('transform',`translate(${s.pan.x} ${s.pan.y})`);if($('#zoom-value'))$('#zoom-value').textContent=isMobile()?'Read':Math.round(s.zoom*100)+'%'}
function bindCanvas(){let drag=null;const canvas=$('#canvas');canvas.addEventListener('pointerdown',ev=>{if(isMobile()||ev.target.closest('button,[data-node]'))return;drag={x:ev.clientX,y:ev.clientY,px:s.pan.x,py:s.pan.y};canvas.setPointerCapture(ev.pointerId);hideTip()});canvas.addEventListener('pointermove',ev=>{if(!drag)return;const scale=1/s.zoom;s.pan={x:drag.px+(ev.clientX-drag.x)*scale,y:drag.py+(ev.clientY-drag.y)*scale};applyTransform()});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('wheel',ev=>{if(isMobile()||(!ev.ctrlKey&&!ev.metaKey))return;ev.preventDefault();s.zoom=Math.max(.5,Math.min(2.6,s.zoom+(ev.deltaY<0?.1:-.1)));applyTransform()},{passive:false});}
function hideTip(){clearTimeout(tipTimer);const tip=$('#cursor-tip');if(tip)tip.hidden=true}
function positionTip(ev){const tip=$('#cursor-tip');if(tip.hidden||!ev)return;tip.style.left=Math.max(10,Math.min(window.innerWidth-(tip.offsetWidth||260)-12,ev.clientX+18))+'px';tip.style.top=Math.max(10,Math.min(window.innerHeight-tip.offsetHeight-12,ev.clientY+18))+'px'}
function showTip(id,ev,el){if(!s.cursor||isMobile()||ev?.pointerType==='touch'||document.querySelector('dialog[open]'))return;clearTimeout(tipTimer);tipTimer=setTimeout(()=>{if(document.querySelector('dialog[open]'))return;const n=getNode(id),rels=allEdges().filter(e=>e.from===id||e.to===id),sg=suggestions[suggestFor(n)];const tip=$('#cursor-tip');tip.className='cursor-tip';tip.innerHTML=studio?studio.tip(n):`<div class="tip-top">${icon('cursor')}Chapter ${s.chapter} / ${s.tab} · Object insight</div><h3>${esc(n.title)}</h3><p>${esc(n.description)}</p><p>${esc(Object.entries(n.attrs)[0].join(': '))} · ${rels.length} relationships</p><small>${esc(contextFor(n))}<br>Suggested next thought: ${sg.title}</small><small>Click or press Enter to pin attributes and explore the proposal.</small>`;tip.hidden=false;const box=el?.getBoundingClientRect();positionTip(ev||{clientX:box.x+box.width/2,clientY:box.y+box.height/2})},220)}

const blankJourney=()=>isBlankProject(window.aiwProjectStore?.value?.document||{});
const flowStages=()=>blankJourney()?journeyStages(window.aiwProjectStore.value.document):stages;
function baseFlowText(){if(blankJourney())return s.step<0?'This trace follows your recorded journey order and saved responsibility links. It illustrates the design; no application code is executed.':flowStages()[s.step]?.text||'Add journey steps in Chapter 1 to trace this model.';if(s.step<0)return 'Trace the happy path, or explore a risk hold and a settlement timeout. This is an illustrative simulation.';if(s.scenario==='hold'&&s.step===1)return 'Risk screening holds this instruction. No ledger posting or settlement occurs. A manual review owner must decide the next action.';if(s.scenario==='timeout'&&s.step===3)return 'The settlement response times out. Outcome stays pending; enquire using the existing reference before retrying. Do not assume failure.';return flowStages()[s.step].text}
function flowText(){const base=baseFlowText();return !blankJourney()&&studio?.flowText?studio.flowText(base):base}
function isTerminal(){if(blankJourney())return flowStages().length>0&&s.step===flowStages().length-1;return s.step===4||(s.scenario==='hold'&&s.step===1)||(s.scenario==='timeout'&&s.step===3)}
function renderFlow(){if(s.chapter>=6){patchLiveSurface($('#flow-panel'),studio.failureSurface());return;}if(!$('#flow-panel'))return;const trace=$('.canvas-toolbar [data-action="play"]');if(trace){const label=blankJourney()?(s.playing?'Pause journey':s.flowFinished?'Replay journey':'Trace your journey'):s.playing?'Pause payment':s.flowFinished?'Replay payment':'Trace a payment';trace.setAttribute('aria-label',label);trace.innerHTML=icon(s.playing?'pause':'play')+'<span>'+label+'</span>'}patchLiveSurface($('#flow-panel'),`<header><div class="flow-label"><i class="live-indicator"></i>${blankJourney()?'Your recorded journey':'Payment walkthrough'} <span class="flow-kind" style="font-size:12px">· SIMULATION</span></div><select id="scenario" aria-label="Journey scenario">${blankJourney()?'<option value="success">Recorded journey</option>':`<option value="success" ${s.scenario==='success'?'selected':''}>Successful payment</option><option value="hold" ${s.scenario==='hold'?'selected':''}>Risk hold</option><option value="timeout" ${s.scenario==='timeout'?'selected':''}>Settlement timeout</option>`}</select></header><div class="journey">${flowStages().map((stage,i)=>`<button class="journey-step ${s.step===i?'active':visitedSteps.has(i)?'done':''}" data-stage="${i}" aria-label="Explore step ${i+1}: ${esc(stage.name)}" ${s.scenario==='hold'&&i>1||s.scenario==='timeout'&&i>3?'disabled':''}><span>${visitedSteps.has(i)&&s.step!==i?'✓':String(i+1).padStart(2,'0')}</span>${esc(stage.name)}</button>`).join('')}</div><div class="flow-actions"><small>${s.flowFinished?(s.scenario==='success'?(visitedSteps.size===flowStages().length?'Journey complete · '+flowStages().length+' steps traced':'At final step · Replay to explore every step'):'Journey stopped · Review required'):'Moving dots show direction; dashed lines show structure.'}</small><div class="action-row"><button class="btn icon-only" data-action="restart-flow" aria-label="Restart walkthrough">${icon('rewind')}</button><button class="btn" data-action="step-flow" ${isTerminal()?'disabled':''}>Step${icon('chevron')}</button><button class="btn" data-action="play">${icon(s.playing?'pause':'play')}${s.playing?'Pause':s.flowFinished?'Replay':'Play'}</button></div></div><p class="journey-copy" role="status" aria-live="polite">${esc(flowText())}</p>${studio?studio.scenarioAction():''}`);}
function goStage(step){if(!Number.isInteger(step)||step<0||step>=flowStages().length||(s.scenario==='hold'&&step>1)||(s.scenario==='timeout'&&step>3))return;visitedSteps.add(step);s.step=step;s.selected=studio?.flowNode?.(flowStages()[step].node)||flowStages()[step].node;const flowLayer=s.chapter===5?'physical':'logical';if(!s.visible.includes(flowLayer)){s.visible.push(flowLayer);render()}drawGraph();refreshInspector();renderFlow()}
function advance(){if(isTerminal()){s.playing=false;s.flowFinished=true;if(s.scenario==='success'&&visitedSteps.size===flowStages().length)mark('flow');renderFlow();return}goStage(s.step+1);if(s.playing)flowTimer=setTimeout(advance,2100);else if(isTerminal()){s.flowFinished=true;if(s.scenario==='success'&&visitedSteps.size===flowStages().length)mark('flow');renderFlow()}}
function play(){if(!flowStages().length){toast('Add a journey step in Chapter 1, then connect its responsibility in Chapter 4.');return;}if(s.tab!=='model'){s.tab='model';render()}if(s.playing){s.playing=false;clearTimeout(flowTimer);drawGraph();renderFlow();return}if(isTerminal()){s.step=-1;s.flowFinished=false;visitedSteps.clear()}s.playing=true;advance()}
function preview(id){if(studio)return studio.preview(id);if(!suggestions[id]||s.accepted.includes(id))return;closeModal();s.ghost=id;s.tab='model';s.selected=id;s.visible=[...new Set([...s.visible,suggestions[id].layer,getNode(suggestions[id].source).layer])];s.zoom=1;s.pan={x:0,y:0};render();toast('Ghost preview · Review the effect before adding it to your working model.')}
function accept(id){if(studio)return studio.accept(id);if(!suggestions[id]||s.accepted.includes(id))return;s.accepted.push(id);s.ghost=null;s.selected=id;mark('candidate');unmark('validate');unmark('export');persist();render();toast(`${suggestions[id].title} added as a working candidate. Validation needs to be rerun.`)}
function remove(id){s.accepted=s.accepted.filter(x=>x!==id);s.selected=suggestions[id].source;if(!s.accepted.length)unmark('candidate');unmark('validate');unmark('export');persist();render();toast('Candidate removed. The original model is restored for this change.')}
function toggleLayer(id){studio?.pause?.();s.playing=false;clearTimeout(flowTimer);hideTip();s.tab='model';s.layerOpen=false;s.visible=s.visible.includes(id)?s.visible.filter(x=>x!==id):[...s.visible,id];if(s.visible.includes('process')&&s.visible.includes('logical'))mark('layers4');if(s.visible.includes('physical'))mark('physical');s.zoom=1;s.pan={x:0,y:0};persist();// The chapter models' diagrams strip to the same layers (notation-view.js listens).
if(typeof CustomEvent==='function'&&typeof window!=='undefined'&&window.dispatchEvent)window.dispatchEvent(new CustomEvent('aiw:model-layers',{detail:[...s.visible]}));render()}
// A chapter model's own Layers menu tells the sidebar, which redraws its strip alone.
window.aiwSetModelLayers=layersNow=>{if(!Array.isArray(layersNow))return;s.visible=layers.map(l=>l.id).filter(id=>layersNow.includes(id));persist();const strip=document.querySelector('.ux-layer-strip');if(strip)strip.outerHTML=layerControls();const rail=document.querySelector('.journey-explorer');if(rail){rail.querySelectorAll('.rail-layer[data-layer]').forEach(b=>{const on=s.visible.includes(b.dataset.layer);b.setAttribute('aria-pressed',String(on));const c=b.querySelector('.rail-layer-check');if(c)c.textContent=on?'✓':'';});const hint=rail.querySelector('.rail-view-hint');if(hint)hint.textContent=`${s.visible.length} of ${layers.length} visible · One connected model`;const all=rail.querySelector('header button');if(all)all.textContent=s.visible.length===layers.length?'Clear':'Show all';}};
function next(){if(studio)return studio.next();const id=nextTask().id;switch(id){case 'inspect':setTab('model');toast('Click a model object to explore its attributes and relationships.');break;case 'layers4':s.visible=[...new Set([...s.visible,'process','logical'])];mark('layers4');setTab('model');break;case 'flow':s.scenario='success';s.step=-1;s.flowFinished=false;visitedSteps.clear();s.playing=false;clearTimeout(flowTimer);play();break;case 'review4':setTab('work');break;case 'chapter5':setChapter(5);break;case 'physical':s.visible=[...new Set([...s.visible,'physical','logical'])];mark('physical');setTab('model');break;case 'candidate':preview('recovery');break;case 'validate':setTab('validate');break;default:setTab('output')}}
function exportModel(reading=false){mark('export');persist();const ns=allNodes().filter(n=>!n.ghost),es=allEdges().filter(e=>ns.some(n=>n.id===e.from)&&ns.some(n=>n.id===e.to));const data={schemaVersion:'aiw.explorer.v1',title:'Bank payment journey',status:'Illustrative working draft — not approved for implementation',exportedAt:new Date().toISOString(),chapter:s.chapter,visibleLayers:s.visible,nodes:ns,relationships:es,workingCandidates:s.accepted.map(id=>suggestions[id]),architectNote:s.note,explorationMilestones:s.completed,validation:{runForCurrentModel:done('validate'),findings:findings()},limitations:['Reference data only; no live bank integration','Rule-based guidance; no connected LLM','Browser-local persistence','Structural checks are not governance approval']};const md=`# AIW V5 · Bank payment journey\n\nIllustrative working architecture — pending independent review.\n\n## Chapter 4 · Logical application\n\n${nodes.filter(n=>n.layer==='logical').map(n=>`- **${esc(n.title)}:** ${n.description}`).join('\n')}\n\n## Chapter 5 · Application realisation\n\n${nodes.filter(n=>n.layer==='physical').map(n=>`- **${esc(n.title)}:** ${n.description}`).join('\n')}\n\n## Working candidates\n\n${s.accepted.length?s.accepted.map(id=>`- **${suggestions[id].title}:** ${suggestions[id].effect}`).join('\n'):'No additional candidates retained.'}\n\n## Architect’s note\n\n${s.note||'No note recorded.'}\n\n## Review findings\n\n${findings().map(f=>`- **${f.title}:** ${f.text}`).join('\n')}\n\n## Limitations\n\nReference data; rule-based guidance; browser-local persistence; no live integration or production certification.\n`;const blob=new Blob([reading?md:JSON.stringify(data,null,2)],{type:reading?'text/markdown':'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=reading?'AIW_V5_Bank_Payment_Reading.md':'AIW_V5_Bank_Payment_Model.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(reading?'Architecture reading exported.':'Connected model exported with candidates and open review findings.');updateProgress()}
function modal(kind){if(studio&&['sol','mind'].includes(kind))return studio.assistant(kind);hideTip();lastFocus=document.activeElement;s.modal=kind;const n=getNode(s.selected),sid=suggestFor(n),sg=suggestions[sid];let title,body;
  if(kind==='sol'){title='A spark for this object.';body=`<p><strong>${esc(n.title)}</strong> · Chapter ${s.chapter} / ${s.tab}</p><div class="context-ribbon">${contextFor(n)}</div><h3>Explain the relationships</h3><p>${allEdges().filter(e=>e.from===n.id||e.to===n.id).map(e=>`${esc(getNode(e.from).title)} ${esc(e.label)} ${esc(getNode(e.to).title)}.`).join(' ')}</p><h3>What could improve this design?</h3><p>${sg.reason}</p><button class="btn gold" data-propose="${sid}" ${s.accepted.includes(sid)?'disabled':''}>${icon('spark')}${s.accepted.includes(sid)?'Candidate already added':'Preview '+sg.title}</button>`}
  else if(kind==='mind'){title='Mind Factory';body=`<p>Explore a pattern in the context of <strong>${esc(n.title)}</strong>. These are architecture prompts for review.</p>${[['review','Human review boundary','Separates the automated hold decision from authorised human release.','Requires an accountable owner, review SLA, audit trail, and release authority.'],['dedup','Idempotent processing','Makes repeat instructions return a known outcome instead of repeating the financial effect.','Requires a stable reference, atomicity with posting, and an explicit retention policy.'],['recovery','Controlled recovery','Separates an uncertain outcome from a failed payment.','Requires status enquiry, bounded retries, reconciliation, monitoring, and a runbook.']].map(([id,t,fit,trade])=>`<div class="knowledge-card"><h3>${t}</h3><p>${fit}<br><strong>Obligations:</strong> ${trade}</p><button class="text-button" data-propose="${id}" ${s.accepted.includes(id)?'disabled':''}>${s.accepted.includes(id)?'Working candidate added':'Explore on the model →'}</button></div>`).join('')}`}
  else if(kind==='relations'){title=n.title+' relationships';body=allEdges().filter(e=>e.from===n.id||e.to===n.id).map(e=>`<div class="knowledge-card"><p><strong>${esc(getNode(e.from).title)}</strong> ${esc(e.label)} <strong>${esc(getNode(e.to).title)}</strong></p><button class="text-button" data-select="${e.from===n.id?e.to:e.from}">Explore related object →</button></div>`).join('')}
  else {title='A small, living AIW prototype.';body=`<p>This explorer carries forward the warm paper, forest green, and gold direction of the earlier AIW Chapter 5 concept. Chapters 4–9 share one graph and the Work, Model, Validate, Output rhythm.</p><h3>What is real here</h3><p>Layer filtering, connected object inspection, scenario playback, chapter-aware guidance, reviewable ghost proposals, structural checks, and model export.</p><h3>What is illustrative</h3><p>The bank architecture and its implementations are sample data. Flow animation is a teaching simulation. Chapter guidance uses explicit model rules. Sol and Mind Factory can also use the configured OpenAI connection; its current status and exact source packet are shown before generation.</p><h3>Your working state</h3><p>Requirements, quality drivers, decisions, logical responsibilities, connections, implementation mappings, technology capabilities, technology choices, and interface/data definitions use your private project storage. View preferences and earlier architecture notes stay in this browser.</p><h3>Canvas controls</h3><p>Hover for a quick explanation. Click or press Enter to pin an object. Drag the background to pan; use + / − or Ctrl + scroll to zoom. Fit returns to the full model. Reduced-motion preferences disable ambient dots.</p>`}
  $('#dialog-host').innerHTML=`<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><span class="eyebrow">${kind==='mind'?'Knowledge in context':kind==='sol'?'Sol menu':'AIW V5'}</span><button class="btn icon-only" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></header><h2 id="dialog-title">${title}</h2>${body}</section></div>`;$('#dialog-host [data-action="close-modal"]').focus();
}
function closeModal(){s.modal=null;if($('#dialog-host'))$('#dialog-host').innerHTML='';lastFocus?.isConnected&&lastFocus.focus()}
document.addEventListener('click',ev=>{const button=ev.target.closest('button,[data-node]');if(!button){if(ev.target.classList.contains('dialog-backdrop'))closeModal();return}if(button.disabled||studio?.busy)return;
  if(button.dataset.chapter)return setChapter(Number(button.dataset.chapter));if(button.dataset.tab)return setTab(button.dataset.tab);if(button.dataset.layer){if(!button.closest('.journey-explorer'))s.layersExpanded=true;return toggleLayer(button.dataset.layer);}if(button.dataset.node){hideTip();return selectNode(button.dataset.node,true)}if(button.dataset.select){closeModal();return selectNode(button.dataset.select)}if(button.dataset.propose)return preview(button.dataset.propose);if(button.dataset.accept)return accept(button.dataset.accept);if(button.dataset.remove)return remove(button.dataset.remove);if(button.dataset.stage!==undefined){clearTimeout(flowTimer);s.playing=false;s.flowFinished=false;goStage(Number(button.dataset.stage));return}
  switch(button.dataset.action){case 'next-context':next();break;case 'focus-model':s.focus=!s.focus;if(s.focus&&!s.visible.includes(getNode(s.selected).layer))s.visible.push(getNode(s.selected).layer);s.zoom=1;s.pan={x:0,y:0};persist();render();restoreButton('focus-model');break;case 'expand-model':s.expanded=!s.expanded;render();restoreButton('expand-model');break;case 'back-canvas':$('#canvas')?.scrollIntoView({block:'start',behavior:'auto'});break;case 'layers-menu':s.layerOpen=!s.layerOpen;render();break;case 'all-layers':s.layerOpen=false;s.visible=s.visible.length===8?[]:layers.map(l=>l.id);if(s.visible.length){mark('layers4');mark('physical')}s.zoom=1;s.pan={x:0,y:0};setTab('model');break;case 'default-layers':s.visible=['process','logical'];mark('layers4');render();break;case 'cursor':s.cursor=!s.cursor;saveCursorPreference(s.cursor);persist();render();toast(s.cursor?'Generative cursor on · Hover or focus an object.':'Generative cursor off · Click objects to use the inspector.');break;case 'motion':s.animate=!s.animate;persist();render();break;case 'zoom-in':s.zoom=Math.min(2.6,s.zoom+.2);applyTransform();break;case 'zoom-out':s.zoom=Math.max(.1,s.zoom-.2);applyTransform();break;case 'fit':s.zoom=isMobile()?1:Math.min(1,($('#canvas')?.clientWidth||graphWidth)/graphWidth,Math.max(100,($('#canvas')?.clientHeight||graphHeight)-60)/graphHeight);s.pan={x:0,y:0};applyTransform();$('#canvas').scrollLeft=0;$('#canvas').scrollTop=0;break;case 'play':play();break;case 'step-flow':s.playing=false;clearTimeout(flowTimer);advance();break;case 'restart-flow':s.playing=false;s.step=-1;s.flowFinished=false;visitedSteps.clear();clearTimeout(flowTimer);drawGraph();renderFlow();break;case 'sol':modal('sol');break;case 'mind':modal('mind');break;case 'about':modal('about');break;case 'all-relations':modal('relations');break;case 'close-modal':closeModal();break;case 'dismiss':s.selected=suggestions[s.ghost].source;s.ghost=null;render();toast('Ghost preview dismissed.');break;case 'open-model':setTab('model');break;case 'next':next();break;case 'review4':mark('review4');render();toast('Logical model review recorded for this exploration.');break;case 'validate':mark('validate');render();toast('Model checks complete. Open obligations remain visible.');break;case 'export':exportModel();break;case 'export-summary':exportModel(true);break;}
});
document.addEventListener('toggle',ev=>{if(ev.target.matches?.('.ux-layer-strip'))s.layersExpanded=ev.target.open},true);
document.addEventListener('change',ev=>{if(ev.target.id==='scenario'){s.scenario=ev.target.value;s.playing=false;s.step=-1;s.flowFinished=false;visitedSteps.clear();clearTimeout(flowTimer);persist();drawGraph();renderFlow()}});
document.addEventListener('input',ev=>{if(ev.target.id==='architect-note'){s.note=ev.target.value.slice(0,5000);unmark('export');persist();updateProgress()}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){hideTip();if(s.modal)closeModal()}if(ev.key==='Tab'&&s.modal){const els=$$('.dialog button:not(:disabled),.dialog a,.dialog input');const first=els[0],last=els.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus()}}});
window.addEventListener('resize',()=>{hideTip();clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(s.tab==='model')drawGraph()},150)});

function isMobile(){return window.matchMedia('(max-width: 700px)').matches}
function visibleNodes(){
  const visible=allNodes().filter(n=>s.visible.includes(n.layer));
  if(!s.focus)return visible;
  const ids=new Set([s.selected]);
  for(const e of allEdges())if(e.from===s.selected||e.to===s.selected){ids.add(e.from);ids.add(e.to)}
  return visible.filter(n=>ids.has(n.id));
}
function layoutModel(modelNodes,mobile=false,focused=false,grouped=false){
  const positions=new Map(),lanes=[],groupBoxes=[];
  const minCol=focused&&modelNodes.length?Math.min(...modelNodes.map(n=>n.col)):0;
  const available=$('#canvas')?.clientWidth||1200,columns=mobile?1:Math.max(1,Math.min(5,Math.floor((available-40)/232)));
  const width=mobile?Math.max(300,available):Math.max(288,columns*232+40);
  let y=65;
  for(const layer of layers){
    const group=modelNodes.filter(n=>n.layer===layer.id);
    if(!group.length)continue;
    lanes.push({name:layer.name,y:y-18});
    if(grouped&&layer.id==='logical'&&studio){
      const seen=[...new Set(group.map(n=>n.groupId||''))];
      for(const id of seen){const members=group.filter(n=>(n.groupId||'')===id),start=y,columns=Math.max(1,Math.min(5,Math.floor((width-40)/232)));y+=42;members.forEach((n,i)=>positions.set(n.id,{x:mobile?(width-200)/2:28+(i%columns)*232,y:y+(mobile?i:Math.floor(i/columns))*110}));const rows=mobile?members.length:Math.ceil(members.length/columns);y+=rows*110;groupBoxes.push({x:16,y:start,width:width-32,height:y-start-16,title:studio.groups.find(g=>g.id===id)?.title||'Ungrouped'});y+=25;}
    }else if(mobile){for(const n of group){positions.set(n.id,{x:(width-200)/2,y});y+=110}y+=35}
    else{
      const occupancy=new Set();let rows=0;for(const n of group){const col=Math.max(0,n.col-minCol)%columns;let row=Math.floor(Math.max(0,n.col-minCol)/columns);while(occupancy.has(row+':'+col))row++;occupancy.add(row+':'+col);positions.set(n.id,{x:28+col*232,y:y+row*108});rows=Math.max(rows,row+1)}
      y+=rows*108+27;
    }
  }
  return {positions,lanes,groups:groupBoxes,width,height:Math.max(280,y+25)};
}
function searchNodes(query){
  const terms=String(query).trim().toLowerCase().split(/\s+/).filter(Boolean);
  if(!terms.length)return [];
  const queryText=terms.join(' ');
  const score=n=>n.title.toLowerCase()===queryText?3:terms.every(term=>n.title.toLowerCase().includes(term))?2:n.title.toLowerCase().startsWith(terms[0])?1:0;
  return allNodes().filter(n=>{const text=[n.title,n.description,layerOf(n).name,...Object.values(n.attrs)].join(' ').toLowerCase();return terms.every(term=>text.includes(term))}).sort((a,b)=>score(b)-score(a)).slice(0,8);
}
function layerControls(){return `<details class="ux-layer-strip" ${s.layersExpanded?'open':''}><summary><b>Model layers</b><span>${s.visible.length} of ${layers.length} visible</span><small>One connected model</small></summary><div class="ux-layer-buttons">${layers.map(l=>`<button class="layer-toggle" data-layer="${l.id}" style="--layer:${l.color}" aria-pressed="${s.visible.includes(l.id)}">${icon(l.icon)}${l.name}<span class="check">${s.visible.includes(l.id)?icon('check'):''}</span></button>`).join('')}</div><p>Layer visibility changes the view. Your objects and relationships stay in the shared project.</p></details>`}
function explorationControls(){return `<div class="exploration-controls"><div class="model-search"><label class="visually-hidden" for="model-search">Find an object across all layers</label><input id="model-search" type="search" autocomplete="off" placeholder="Find an object, owner, or responsibility…" aria-controls="search-results"><div id="search-results" class="search-results" hidden></div></div><button class="btn" data-action="focus-model" aria-pressed="${s.focus}">${icon('eye')}<span>${s.focus?'Show context':'Focus object'}</span></button><button class="btn icon-only expand-button" data-action="expand-model" aria-label="${s.expanded?'Restore sidebar':'Widen canvas'}" aria-pressed="${s.expanded}">${icon('fit')}</button></div>`}
function bindSearch(){
  const input=$('#model-search'),results=$('#search-results');if(!input||!results)return;
  input.addEventListener('input',()=>{
    s.query=input.value;const found=searchNodes(s.query);
    results.hidden=!s.query.trim();
    results.innerHTML=found.length?found.map(n=>`<button data-search-select="${n.id}"><strong>${esc(n.title)}</strong><small>${layerOf(n).name}${s.visible.includes(n.layer)?'':' · Reveal layer'}</small></button>`).join(''):`<p>No objects match “${esc(s.query)}”.</p>`;
  });
  input.addEventListener('keydown',ev=>{if(ev.key==='ArrowDown'){ev.preventDefault();results.querySelector('button')?.focus()}if(ev.key==='Enter'){ev.preventDefault();const first=searchNodes(input.value)[0];if(first)chooseSearch(first.id)}if(ev.key==='Escape'){results.hidden=true;}});
  results.addEventListener('click',ev=>{const b=ev.target.closest('[data-search-select]');if(b)chooseSearch(b.dataset.searchSelect)});
  results.addEventListener('keydown',ev=>{const buttons=[...results.querySelectorAll('button')],index=buttons.indexOf(document.activeElement);if(ev.key==='ArrowDown'){ev.preventDefault();buttons[(index+1)%buttons.length]?.focus()}if(ev.key==='ArrowUp'){ev.preventDefault();if(index===0)input.focus();else buttons[index-1]?.focus()}if(ev.key==='Escape'){results.hidden=true;input.focus()}});
}
function chooseSearch(id){s.query='';s.focus=true;selectNode(id);persist();render();const n=$(`[data-node="${id}"]`);n?.focus();n?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'auto'});toast(`${getNode(id).title} · Showing its immediate relationships.`)}
function restoreButton(action){$(`[data-action="${action}"]`)?.focus()}
document.addEventListener('pointerdown',hideTip);
document.addEventListener('pointerover',ev=>{const el=ev.target.closest?.('[data-select]');if(el)showTip(el.dataset.select,ev)});
document.addEventListener('pointerout',ev=>{if(ev.target.closest?.('[data-select]'))hideTip()});
document.addEventListener('focusin',ev=>{const el=ev.target.closest?.('[data-select]');if(el)showTip(el.dataset.select,null,el)});
document.addEventListener('focusout',ev=>{if(ev.target.closest?.('[data-select]'))hideTip()});
document.addEventListener('click',ev=>{if(!ev.target.closest('.model-search')&&$('#search-results')){$('#search-results').hidden=true;}});

studio?.bind({state:s,getNode,icon,render,refreshGraph:drawGraph,refreshSimulation(){drawGraph();renderFlow()},toast,selectNode,setTab,setChapter,mark,unmark,persist,closeModal,pauseFlow(){s.playing=false;clearTimeout(flowTimer)},visited:()=>[...visitedSteps],isTerminal});
