function sourceRequirements(id){
  const records=window.aiwProjectStore?.value?.document?.artefacts.filter(a=>a.type==='requirement'&&a.modelRef===id)||[];
  return records.length?`<div class="upstream-requirements"><h3>Source requirements</h3>${records.map(a=>`<a href="/?chapter=1&tab=work&artefact=${a.id}"><b>${esc(a.id)}</b> ${esc(a.title)}<small>${a.confirmed?'User-confirmed':'Unconfirmed reference or draft'}</small></a>`).join('')}</div>`:'';
}

function sourceQualityDrivers(id){
  const project=window.aiwProjectStore?.value?.document;
  const records=project?.quality?.drivers.filter(d=>d.responsibilityIds.includes(id))||[];
  return records.length?`<div class="upstream-requirements"><h3>Quality drivers</h3>${records.map(d=>`<a href="/?chapter=2&tab=model&driver=${d.id}"><b>${esc(d.id)}</b> ${esc(d.title)}<small>${esc(d.metric)} · ${esc(d.operator)} ${esc(d.targetValue)} ${esc(d.unit)} · ${d.targetConfirmed?'Target confirmed':'Target assumption'}</small>${d.tactic?`<small>Candidate tactic: ${esc(d.tactic)}</small>`:''}</a>`).join('')}</div>`:'';
}

function sourceDecisions(id){const records=window.aiwDecisionContext?.recordsFor(id)||[];return records.length?`<div class="upstream-requirements"><h3>Architecture decisions</h3>${records.map(d=>`<a href="/?chapter=3&tab=model&decision=${d.id}"><b>${esc(d.id)} · r${d.revision}</b> ${esc(d.question)}<small>${esc(d.choice?.title||'Choice under revision')}</small><small>${d.current?'Architect accepted':d.status==='draft'?'Draft revision':d.status==='recorded'?'Recorded · acceptance required':d.status==='superseded'?'Superseded':'Inputs changed · review required'} · ${d.impactCurrent?'Model impact applied':'Impact not active'}</small><small>${esc(d.governanceLabel)}</small><small>Reason: ${esc(d.rationale)}</small></a>`).join('')}</div>`:'';}

